ss=np.sum((y-y.mean())**2)
def fit(extra, a):
    cols=[np.tanh(a*t)]
    for i in range(4):
        for j in range(4):
            for k in range(3):
                if i+j+k<=4: cols.append(t**i*x**j*v**k)
